'use strict';

/*
 * The API data, loaded once and indexed.
 *
 * `data/api.json` is generated by `tools/generate-api.js` from the sources of the mod: there is no
 * hand-written list here. The file is read on the first request, not on activation, so opening a
 * `.bs` file does not pay the cost for someone who never uses completion.
 */

const fs = require('fs');
const path = require('path');

let data = null;
/** symbol -> name of the module that exports it (the first one, the way StdLib.homeModuleOf does) */
let homeModule = null;
/** event name -> description */
let eventByName = null;

function load() {
    if (data) return data;
    data = JSON.parse(fs.readFileSync(path.join(__dirname, '..', 'data', 'api.json'), 'utf8'));
    homeModule = new Map();
    for (const [moduleName, module] of Object.entries(data.modules)) {
        for (const symbol of Object.keys(module.symbols)) {
            if (!homeModule.has(symbol)) homeModule.set(symbol, moduleName);
        }
    }
    eventByName = new Map(data.events.map((event) => [event.name, event]));
    return data;
}

/** The module to import in order to use `symbol`, or null when it is not a library symbol. */
function homeModuleOf(symbol) {
    load();
    return homeModule.get(symbol) || null;
}

function moduleNames() {
    return Object.keys(load().modules);
}

function moduleOf(name) {
    return load().modules[name] || null;
}

function symbolsOf(moduleName) {
    const module = moduleOf(moduleName);
    return module ? Object.keys(module.symbols) : [];
}

function symbolInfo(moduleName, symbol) {
    const module = moduleOf(moduleName);
    return module ? module.symbols[symbol] || null : null;
}

function events() {
    return load().events;
}

function eventInfo(name) {
    load();
    return eventByName.get(name) || null;
}

function prelude() {
    return load().prelude;
}

/** The documentation of a function of the prelude, or null when the name is not one of them. */
function preludeInfo(name) {
    const symbols = load().preludeSymbols || {};
    return symbols[name] || null;
}

function keywords() {
    return load().keywords;
}

function constants() {
    return load().constants;
}

function types() {
    return load().types;
}

/**
 * Bounded edit distance: it only serves to say "did you mean", so as soon as it goes past the
 * threshold it stops computing instead of filling a whole matrix.
 */
function editDistance(a, b, limit) {
    if (Math.abs(a.length - b.length) > limit) return limit + 1;
    let beforePrevious = null;
    let previous = Array.from({ length: b.length + 1 }, (_, i) => i);
    for (let i = 1; i <= a.length; i++) {
        const current = [i];
        let best = i;
        for (let j = 1; j <= b.length; j++) {
            const cost = a[i - 1] === b[j - 1] ? 0 : 1;
            current[j] = Math.min(previous[j] + 1, current[j - 1] + 1, previous[j - 1] + cost);
            // transposition: 'sqtr' for 'sqrt' is a slip of the fingers, not two substitutions
            if (i > 1 && j > 1 && a[i - 1] === b[j - 2] && a[i - 2] === b[j - 1]) {
                current[j] = Math.min(current[j], beforePrevious[j - 2] + 1);
            }
            if (current[j] < best) best = current[j];
        }
        if (best > limit) return limit + 1;
        beforePrevious = previous;
        previous = current;
    }
    return previous[b.length];
}

/** The candidate closest to `name` among `candidates`, or null when none is close enough. */
function suggest(name, candidates) {
    const limit = name.length <= 4 ? 1 : 2;
    let best = null;
    let bestDistance = limit + 1;
    for (const candidate of candidates) {
        const distance = editDistance(name, candidate, limit);
        if (distance < bestDistance) {
            bestDistance = distance;
            best = candidate;
        }
    }
    return bestDistance <= limit ? best : null;
}

module.exports = {
    load,
    homeModuleOf,
    moduleNames,
    moduleOf,
    symbolsOf,
    symbolInfo,
    events,
    eventInfo,
    prelude,
    preludeInfo,
    keywords,
    constants,
    types,
    suggest
};
